<script setup>
import {ref,onBeforeUnmount} from 'vue';
import {showToast} from 'vant';
import DevicePairing from './components/DevicePairing.vue';
import RestReminder from './components/RestReminder.vue';
import ImageCropper from './components/ImageCropper.vue';
import PreviewLesson from './components/PreviewLesson.vue';
import ReviewPractice from './components/ReviewPractice.vue';
import HandwritingFeedback from './components/HandwritingFeedback.vue';
import ResultEvidence from './components/ResultEvidence.vue';
defineProps(['tab']);const emit=defineEmits(['navigate']);
const files=ref([]),input=ref(),attempted=ref(false),stage=ref('upload'),error=ref(''),answer=ref(''),hint=ref(false),corrected=ref(false),bound=ref(true),cropPhoto=ref(null),failNext=ref(false),progress=ref(0),batch=ref(''),attempts=ref([]),pending=ref(false),session=ref(0);let timer,progressTimer,batchSequence=0;
function pick(e){error.value='';for(const f of e.target.files){if(files.value.length===9){error.value='一次最多选择 9 张图片';break;}if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){error.value='请选择每张不超过 10 MiB 的 JPG、PNG 或 WebP 图片';continue;}files.value.push({url:URL.createObjectURL(f),name:f.name,rotation:0});}e.target.value='';}
function remove(i){URL.revokeObjectURL(files.value[i].url);files.value.splice(i,1);}
function move(i,direction){const target=i+direction;if(target<0||target>=files.value.length)return;const [photo]=files.value.splice(i,1);files.value.splice(target,0,photo);}
function applyCrop({photo,blob,width,height}){const item=files.value.find(f=>f===photo);if(!item)return;URL.revokeObjectURL(item.url);item.url=URL.createObjectURL(blob);item.name=`裁剪-${width}×${height}.png`;item.rotation=0;cropPhoto.value=null;}
function cancel(){clearTimeout(timer);clearInterval(progressTimer);stage.value='upload';progress.value=0;}
function run(){stage.value='processing';progress.value=10;progressTimer=setInterval(()=>progress.value=Math.min(90,progress.value+25),350);timer=setTimeout(()=>{clearInterval(progressTimer);progress.value=100;if(failNext.value){failNext.value=false;stage.value='failed';}else stage.value='result';},1400);}
function submit(){if(!attempted.value){error.value='请先确认已经独立尝试完成作业';return;}if(!files.value.length){error.value='请先选择至少一张图片';return;}error.value='';batch.value=`DEMO-${String(++batchSequence).padStart(3,'0')}`;run();}
function revoke(){cancel();bound.value=false;files.value.forEach(f=>URL.revokeObjectURL(f.url));files.value=[];cropPhoto.value=null;attempted.value=false;answer.value='';hint.value=false;corrected.value=false;attempts.value=[];error.value='';batch.value='';failNext.value=false;pending.value=false;session.value++;}
function connected(){bound.value=true;emit('navigate','home');}
function correct(){if(!answer.value.trim()){showToast('先写下你的想法吧');return;}corrected.value=answer.value.replace(/[^0-9.]/g,'')==='26';attempts.value.push({answer:answer.value,result:corrected.value?'示例订正正确':'继续订正'});if(!corrected.value){hint.value=true;showToast('再想一想：四条边分别是多少？');}}
onBeforeUnmount(()=>{clearTimeout(timer);clearInterval(progressTimer);files.value.forEach(f=>URL.revokeObjectURL(f.url));});
</script>
<template>
<section v-show="tab==='pairing'||!bound"><DevicePairing :bound="bound" @bind="connected" @revoke="revoke"/></section>
<section v-show="bound&&tab!=='pairing'"><RestReminder :key="session"/></section>
<template v-if="bound">
<template v-if="tab==='home'">
<PageHead eyebrow="MY LEARNING / 今天的学习" title="林同学，准备好一起探索了吗？" description="不用着急。认真完成一小步，就是今天的进步。"><template #actions><span class="date-chip"><Icon name="calendar"/>固定演示课表 · 10 月 26 日</span></template></PageHead>
<div class="learning-hero"><div><span class="hero-label">今天的小目标</span><h2>先自己试试，<br>再和小知一起检查。</h2><p>数学 · 长方形和正方形　约 15 分钟</p><van-button type="primary" @click="emit('navigate','homework')"><Icon name="camera"/>开始拍作业<Icon name="arrow"/></van-button></div><div class="geometry-art" aria-hidden="true"><span class="art-note">周长 = 四条边的总和</span><div class="ruler-shape"><span>8 cm</span><b>5 cm</b><i/></div><div class="art-badge"><Icon name="sparkles"/>我会认真试一试</div></div></div>
<div class="section-title"><div><span class="eyebrow">ONE STEP AT A TIME</span><h2>今天的学习路线</h2></div><span class="muted">按自己的节奏完成</span></div><div class="learning-route"><button class="route-card" @click="emit('navigate','homework')"><span class="route-icon blue"><Icon name="camera" :size="28"/></span><span class="route-step">第 1 步 · 约 8 分钟</span><h3>拍下认真写的作业</h3><p>清晰拍照，让小知帮你检查。</p><span class="text-action">去拍作业 <Icon name="arrow"/></span></button><button class="route-card" @click="emit('navigate','mistakes')"><span class="route-icon amber"><Icon name="pencil" :size="28"/></span><span class="route-step">第 2 步 · 约 5 分钟</span><h3>再试一道小难题</h3><p>{{corrected?'你已完成一道订正，做得好。':'从一个小提示开始，自己找到方法。'}}</p><span class="text-action">{{corrected?'查看我的订正':'去订正'}} <Icon name="arrow"/></span></button><button class="route-card" @click="emit('navigate','preview')"><span class="route-icon mint"><Icon name="book" :size="28"/></span><span class="route-step">第 3 步 · 约 2 分钟</span><h3>看看明天学什么</h3><p>认识新知识，带着问题去上课。</p><span class="text-action">去预习 <Icon name="arrow"/></span></button></div><div class="gentle-note"><Icon name="heart"/><div><strong>今天也记得让眼睛休息一下</strong><p>学习 20 分钟后，看看远处。小知是 AI 助手，也可能看错，有疑问可以请家长一起确认。</p></div></div>
</template>
<template v-else-if="tab==='homework'"><PageHead eyebrow="HOMEWORK / 作业检查" title="把你的认真拍下来" description="先独立尝试，再来检查。只拍作业，注意避开姓名和人脸。"/><div class="panel"><van-steps :active="stage==='upload'?0:stage==='processing'?1:2"><van-step>选择照片</van-step><van-step>检查中</van-step><van-step>查看结果</van-step></van-steps><template v-if="stage==='upload'"><button class="upload-zone" @click="input.click()"><span class="upload-icon"><Icon name="camera" :size="32"/></span><h3>拍照或从相册选择</h3><p>1–9 张 · 每张不超过 10 MiB · JPG / PNG / WebP</p><span class="text-action">选择作业照片 <Icon name="plus"/></span></button><input ref="input" class="sr-only" type="file" accept="image/jpeg,image/png,image/webp" multiple @change="pick"/><div class="photo-grid"><div v-for="(f,i) in files" :key="f.url" class="photo-card"><img :src="f.url" :style="{transform:`rotate(${f.rotation}deg)`}" alt="本地选择的作业照片"/><span>{{i+1}} · {{f.name}}</span><div><button class="icon-button" :aria-label="`旋转第${i+1}张`" @click="f.rotation+=90"><Icon name="rotate"/></button><button class="icon-button" :aria-label="`裁剪第${i+1}张`" @click="cropPhoto=f"><Icon name="pencil"/></button><button class="icon-button" :aria-label="`前移第${i+1}张`" :disabled="i===0" @click="move(i,-1)"><Icon name="left"/></button><button class="icon-button" :aria-label="`后移第${i+1}张`" :disabled="i===files.length-1" @click="move(i,1)"><Icon name="right"/></button><button class="icon-button" :aria-label="`移除第${i+1}张`" @click="remove(i)"><Icon name="trash"/></button></div></div></div><details class="demo-controls"><summary>检查异常演示</summary><label><input v-model="failNext" type="checkbox"/>模拟本次检查网络中断</label><p>重试沿用同一演示批次，不重新生成任务或扣额。</p></details><label class="attempt-check"><input v-model="attempted" type="checkbox"/>我已经自己试着完成了这些题</label><p v-if="error" role="alert" class="error-message">{{error}}</p><div class="button-row"><van-button type="primary" @click="submit">开始检查 · {{files.length}} 张</van-button><span class="muted">照片只在本地预览；结果使用固定示例</span></div></template><div v-else-if="stage==='processing'" class="empty-state"><Icon name="activity" :size="48"/><h2>正在演示作业检查流程</h2><p>识别题目 → 检查作答 → 整理提示</p><progress class="task-progress" :value="progress" max="100" aria-label="示例检查进度"/><p>批次 {{batch}} · 未调用 AI</p><van-button plain @click="cancel">取消本次检查</van-button></div><div v-else-if="stage==='failed'" class="empty-state" role="status"><Icon name="alert" :size="42"/><h2>检查暂时中断，照片还在</h2><p>网络中断示例 · 批次 {{batch}} · 未新增任务或重复扣额</p><div class="button-row"><van-button type="primary" @click="run">使用相同批次重试</van-button><van-button plain @click="cancel">返回编辑照片</van-button></div></div><template v-else><div class="result-banner"><Icon name="tick" :size="32"/><div><h2>检查示例已准备好</h2><p>这是固定示例，不是所选照片的真实批改结果。</p></div></div><ResultEvidence :unclear="pending" @pending="pending=true"/><div class="result-question"><el-tag type="success">第 1 题 · 正确</el-tag><h3>24 ÷ 6 = 4</h3><p>你把除法算对了，继续保持认真。</p></div><div class="result-question"><el-tag type="warning">{{pending?'第 2 题 · 待家长确认':'第 2 题 · 再试一次'}}</el-tag><h3>长方形的长是 8 厘米，宽是 5 厘米，周长是多少？</h3><p>机器原始作答：13 厘米</p><p v-if="pending">当前标记待确认，等待家长核对后再订正。</p><van-button v-if="!pending" type="primary" plain @click="emit('navigate','mistakes')">从提示开始订正</van-button></div><div class="result-question"><el-tag type="info">第 3 题 · 待确认</el-tag><p>示例中的字迹不够清晰，请家长一起核对。待确认不计作错题。</p></div><div class="result-question"><el-tag type="info">第 4 题 · 未作答</el-tag><p>先自己试着写下想法，暂不展示完整答案。</p></div><div class="result-question"><el-tag type="info">第 5 题 · 暂不支持</el-tag><p>示例为开放口语题，请家长或老师核对，不计作错题。</p></div><van-button plain @click="stage='upload'">再检查一份作业</van-button></template></div></template>
<template v-else-if="tab==='mistakes'"><PageHead eyebrow="TRY AGAIN / 订正与复习" title="再试一次，你会更明白" description="今天复习 1 道题，先想一想，再看提示。"/><div class="exercise-layout"><div class="panel exercise"><div class="panel-heading"><el-tag>数学 · 周长</el-tag><span class="muted">第 1 / 1 题</span></div><h2>一块长方形菜地，长 8 米，宽 5 米。围一圈需要多长的围栏？</h2><div class="math-diagram"><span>8 米</span><div/><span>5 米</span></div><p class="muted">上次作答：13 米 · 可以再认真想一想</p><van-field v-model="answer" label="我的新作答" placeholder="写下你的答案和想法" type="textarea" rows="2" maxlength="300"/><div v-if="hint" class="hint-box"><Icon name="sparkles"/><p>周长要把四条边都加起来。长方形有几条长边、几条宽边？</p></div><div class="button-row"><van-button type="primary" @click="correct">检查我的订正</van-button><van-button plain @click="hint=true">给我一点提示</van-button></div><div v-if="corrected" class="result-banner"><Icon name="tick"/><div><h3>这次你把四条边都算上了！</h3><p>8 + 5 + 8 + 5 = 26 米。下次遇到“围一圈”，记得想想四条边。</p></div></div></div><aside class="panel learning-aside"><span class="eyebrow">学习小提醒</span><h3>慢一点，也没关系。</h3><p>遇到不会的题，试试画个图，把已知条件标出来。</p><div class="aside-line"/><Icon name="heart" :size="30"/><p>练习结果仅保留在本次演示。真实复习计划由家长确认。</p><div v-if="attempts.length" class="attempt-history"><h3>我的订正记录</h3><article v-for="(item,i) in attempts" :key="i"><strong>第 {{i+1}} 次 · {{item.result}}</strong><p>{{item.answer}}</p></article><p>原始作答 13 米保持不变；原型自动判定仅用于演示。</p></div></aside></div></template>
<PreviewLesson v-else-if="tab==='preview'"/>
<section v-show="tab==='review'"><ReviewPractice :key="session"/></section>
<section v-show="tab==='handwriting'"><HandwritingFeedback :key="session"/></section>
<ImageCropper :photo="cropPhoto" @close="cropPhoto=null" @apply="applyCrop"/>
</template>
</template>
